func ListValidJSONDirs(resultsDir string) (dirs []string, err error) {
	var dirInfo []fs.DirEntry
	if dirInfo, err = os.ReadDir(resultsDir); err != nil {
		err = xerrors.Errorf("Failed to read %s: %w",
